1	/// Added to every premium, whatever the policy contains.
2	const PROCESSING_FEE: u64 = 5;
3	
4	/// Charged once per component, uniformly for every component type.
5	const COMPONENT_BASE_PREMIUM: u64 = 25;
6	
7	/// Components alike in type are offered as a building block at this premium.
8	const BUILDING_BLOCK_BASE_PREMIUM: u64 = 60;
9	
10	/// A building block is offered for exactly this many alike components.
11	const BUILDING_BLOCK_SIZE: usize = 3;
12	
13	/// The kind of magical item the MHPCO insures.
14	#[derive(PartialEq)]
15	pub enum ItemType {
16	    Sword,
17	    Amulet,
18	    Staff,
19	    Potion,
20	    Rune,
21	    Moonstone,
22	}
23	
24	/// An item a customer wishes to insure.
25	pub struct Item {
26	    pub item_type: ItemType,
27	}
28	
29	/// Computes the premium in whole G for the items a customer wishes to insure.
30	pub fn quote(items: &[Item]) -> u64 {
31	    let main_items: u64 = items
32	        .iter()
33	        .filter(|item| !is_component(&item.item_type))
34	        .map(base_premium)
35	        .sum();
36	    let components = components_base_premium(items);
37	    main_items + components + PROCESSING_FEE
38	}
39	
40	/// The base premium in G for every component on the policy, offering a
41	/// building block wherever the customer brings exactly three alike ones.
42	fn components_base_premium(items: &[Item]) -> u64 {
43	    [ItemType::Rune, ItemType::Moonstone]
44	        .iter()
45	        .map(|component_type| {
46	            let alike = items
47	                .iter()
48	                .filter(|item| item.item_type == *component_type)
49	                .count();
50	            if alike == BUILDING_BLOCK_SIZE {
51	                BUILDING_BLOCK_BASE_PREMIUM
52	            } else {
53	                alike as u64 * COMPONENT_BASE_PREMIUM
54	            }
55	        })
56	        .sum()
57	}
58	
59	/// Components, such as runes and moonstones, are the items the MHPCO prices
60	/// uniformly and offers as building blocks.
61	fn is_component(item_type: &ItemType) -> bool {
62	    matches!(item_type, ItemType::Rune | ItemType::Moonstone)
63	}
64	
65	/// The base premium in G the MHPCO charges for one item: a main item has its
66	/// own price-list row; a component is charged the uniform component premium.
67	fn base_premium(item: &Item) -> u64 {
68	    match item.item_type {
69	        ItemType::Sword => 100,
70	        ItemType::Amulet => 60,
71	        ItemType::Staff => 80,
72	        ItemType::Potion => 40,
73	        ItemType::Rune | ItemType::Moonstone => COMPONENT_BASE_PREMIUM,
74	    }
75	}
