p='src/lib.rs'
s=open(p).read()
start=s.index('/// Components, such as runes and moonstones')
end=s.index('#[cfg(test)]')
new = '''/// Components, such as runes and moonstones, are the items the MHPCO has no
/// price-list row for: it prices them uniformly and offers building blocks.
fn is_component(item_type: &ItemType) -> bool {
    main_item_base_premium(item_type).is_none()
}

/// The base premium in G the MHPCO charges for one main item, straight from
/// its price list.
fn base_premium(item: &Item) -> u64 {
    main_item_base_premium(&item.item_type).unwrap_or(COMPONENT_BASE_PREMIUM)
}

/// The MHPCO price list: a row per main item type, and none for a component.
fn main_item_base_premium(item_type: &ItemType) -> Option<u64> {
    match item_type {
        ItemType::Sword => Some(100),
        ItemType::Amulet => Some(60),
        ItemType::Staff => Some(80),
        ItemType::Potion => Some(40),
        ItemType::Rune | ItemType::Moonstone => None,
    }
}

'''
s = s[:start] + new + s[end:]
open(p,'w').write(s)
EOF
